import React, { useState, useEffect } from 'react';
import {
    Box,
    Container,
    Paper,
    Typography,
    TextField,
    Button,
    Tabs,
    Tab,
    Grid,
    Divider,
    Alert,
    CircularProgress,
    Snackbar,
    Backdrop
} from '@mui/material';
import Barcode from 'react-barcode';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

const API_BASE_URL = 'https://logistics-backend-hu3k.onrender.com';

const Dashboard = () => {
    const [activeTab, setActiveTab] = useState(0);
    const [form, setForm] = useState({
        senderName: '',
        senderAddress: '',
        receiverName: '',
        receiverAddress: ''
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [labelData, setLabelData] = useState(null);
    const [snackbar, setSnackbar] = useState({
        open: false,
        message: '',
        severity: 'info'
    });
    const [backendStatus, setBackendStatus] = useState('checking');

    // Check backend status on component mount
    useEffect(() => {
        const checkBackendStatus = async () => {
            try {
                const response = await fetch(`${API_BASE_URL}/api/health`, {
                    method: 'GET',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                });
                if (response.ok) {
                    setBackendStatus('available');
                } else {
                    setBackendStatus('unavailable');
                }
            } catch (error) {
                console.warn('Backend check failed:', error);
                setBackendStatus('unavailable');
            }
        };

        checkBackendStatus();
    }, []);

    const handleChange = e => {
        setForm({ ...form, [e.target.name]: e.target.value });
    };

    const handleTabChange = (event, newValue) => {
        setActiveTab(newValue);
    };

    const generateDeliveryId = () => {
        const timestamp = new Date().getTime();
        const random = Math.floor(Math.random() * 1000);
        return `DL-${timestamp}-${random}`;
    };

    const generatePDF = (data) => {
        const doc = new jsPDF();
        
        // Add title
        doc.setFontSize(20);
        doc.text('Delivery Label', 105, 20, { align: 'center' });
        
        // Add delivery ID
        doc.setFontSize(12);
        doc.text(`Delivery ID: ${data.deliveryId}`, 20, 40);
        
        // Add sender info
        doc.setFontSize(14);
        doc.text('From:', 20, 60);
        doc.setFontSize(12);
        doc.text(data.senderName, 20, 70);
        doc.text(data.senderAddress, 20, 80);
        
        // Add receiver info
        doc.setFontSize(14);
        doc.text('To:', 20, 100);
        doc.setFontSize(12);
        doc.text(data.receiverName, 20, 110);
        doc.text(data.receiverAddress, 20, 120);
        
        // Add barcode
        try {
            const barcodeElement = document.querySelector('.barcode-container svg');
            if (barcodeElement) {
                // Create a temporary canvas with fixed dimensions
                const canvas = document.createElement('canvas');
                canvas.width = 200;  // Fixed width
                canvas.height = 100; // Fixed height
                const ctx = canvas.getContext('2d');
                
                // Convert SVG to data URL
                const svgData = new XMLSerializer().serializeToString(barcodeElement);
                const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
                const url = URL.createObjectURL(svgBlob);
                
                // Load SVG as image
                const img = new Image();
                img.onload = () => {
                    try {
                        // Clear canvas and draw image
                        ctx.clearRect(0, 0, canvas.width, canvas.height);
                        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                        
                        // Add to PDF
                        const imgData = canvas.toDataURL('image/png');
                        doc.addImage(imgData, 'PNG', 20, 150, 170, 50);
                        
                        // Save PDF
                        doc.save(`delivery-label-${data.deliveryId}.pdf`);
                        
                        // Cleanup
                        URL.revokeObjectURL(url);
                    } catch (err) {
                        console.error('Error adding barcode to PDF:', err);
                        // Fallback to text if image conversion fails
                        doc.text('Barcode: ' + data.deliveryId, 20, 150);
                        doc.save(`delivery-label-${data.deliveryId}.pdf`);
                    }
                };
                
                img.onerror = () => {
                    console.error('Error loading barcode image');
                    // Fallback to text if image loading fails
                    doc.text('Barcode: ' + data.deliveryId, 20, 150);
                    doc.save(`delivery-label-${data.deliveryId}.pdf`);
                };
                
                img.src = url;
            } else {
                // Fallback if barcode element is not found
                doc.text('Barcode: ' + data.deliveryId, 20, 150);
                doc.save(`delivery-label-${data.deliveryId}.pdf`);
            }
        } catch (err) {
            console.error('Error generating PDF:', err);
            // Ultimate fallback
            doc.text('Barcode: ' + data.deliveryId, 20, 150);
            doc.save(`delivery-label-${data.deliveryId}.pdf`);
        }
        
        return doc;
    };

    const handleSubmit = async () => {
        try {
            setLoading(true);
            setError('');
            
            // Generate delivery ID
            const deliveryId = generateDeliveryId();
            
            // Create label data
            const labelData = {
                ...form,
                deliveryId
            };

            // Try to send to backend first if available
            if (backendStatus === 'available') {
                try {
                    const response = await fetch(`${API_BASE_URL}/api/generate-label`, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify(labelData)
                    });

                    if (!response.ok) {
                        throw new Error('Backend service unavailable');
                    }

                    const data = await response.json();
                    setLabelData(data);
                    setSnackbar({
                        open: true,
                        message: 'Label generated successfully using backend service',
                        severity: 'success'
                    });
                } catch (backendError) {
                    console.warn('Backend service unavailable, using local generation:', backendError);
                    setBackendStatus('unavailable');
                    throw backendError;
                }
            } else {
                // Use local generation
                setLabelData(labelData);
                setSnackbar({
                    open: true,
                    message: 'Using local generation (backend unavailable)',
                    severity: 'info'
                });
            }

            setActiveTab(1);
        } catch (err) {
            // If backend fails, use local generation
            setLabelData(labelData);
            setSnackbar({
                open: true,
                message: 'Using local generation (backend unavailable)',
                severity: 'info'
            });
            setActiveTab(1);
        } finally {
            setLoading(false);
        }
    };

    const handleDownload = async () => {
        try {
            setLoading(true);
            setError('');
            
            if (!labelData) {
                throw new Error('No label data available');
            }

            // Try backend download first if available
            if (backendStatus === 'available') {
                try {
                    const response = await fetch(`${API_BASE_URL}/api/download-label/${labelData.deliveryId}`, {
                        method: 'GET',
                    });

                    if (!response.ok) {
                        throw new Error('Backend download failed');
                    }

                    const blob = await response.blob();
                    const url = window.URL.createObjectURL(blob);
                    const a = document.createElement('a');
                    a.href = url;
                    a.download = `delivery-label-${labelData.deliveryId}.pdf`;
                    document.body.appendChild(a);
                    a.click();
                    window.URL.revokeObjectURL(url);
                    document.body.removeChild(a);
                    setSnackbar({
                        open: true,
                        message: 'PDF downloaded successfully from backend',
                        severity: 'success'
                    });
                    return;
                } catch (backendError) {
                    console.warn('Backend download failed, using local generation:', backendError);
                    setBackendStatus('unavailable');
                }
            }

            // If backend fails or is unavailable, generate PDF locally
            const doc = generatePDF(labelData);
            doc.save(`delivery-label-${labelData.deliveryId}.pdf`);
            setSnackbar({
                open: true,
                message: 'PDF generated locally (backend unavailable)',
                severity: 'info'
            });
        } catch (err) {
            setError('Failed to download label. Please try again.');
            console.error('Error:', err);
            setSnackbar({
                open: true,
                message: 'Error downloading PDF',
                severity: 'error'
            });
        } finally {
            setLoading(false);
        }
    };

    const handleCloseSnackbar = () => {
        setSnackbar({ ...snackbar, open: false });
    };

    return (
        <Container maxWidth="md" sx={{ mt: 4 }}>
            <Paper elevation={3} sx={{ p: 3 }}>
                <Typography variant="h4" align="center" gutterBottom>
                    Delivery Label Generator
                </Typography>
                
                {backendStatus === 'checking' && (
                    <Alert severity="info" sx={{ mb: 2 }}>
                        Checking backend connection...
                    </Alert>
                )}
                
                {backendStatus === 'unavailable' && (
                    <Alert severity="warning" sx={{ mb: 2 }}>
                        Using local generation mode (backend unavailable)
                    </Alert>
                )}
                
                {error && (
                    <Alert severity="error" sx={{ mb: 2 }}>
                        {error}
                    </Alert>
                )}

                <Tabs value={activeTab} onChange={handleTabChange} centered sx={{ mb: 3 }}>
                    <Tab label="Order Form" />
                    <Tab label="Label Preview" />
                </Tabs>

                {activeTab === 0 ? (
                    <Box component="form" sx={{ mt: 2 }}>
                        <Typography variant="h6" gutterBottom>Sender Information</Typography>
                        <Grid container spacing={2}>
                            <Grid item xs={12}>
                                <TextField
                                    fullWidth
                                    label="Sender Name"
                                    name="senderName"
                                    value={form.senderName}
                                    onChange={handleChange}
                                    required
                                    disabled={loading}
                                />
                            </Grid>
                            <Grid item xs={12}>
                                <TextField
                                    fullWidth
                                    label="Sender Address"
                                    name="senderAddress"
                                    value={form.senderAddress}
                                    onChange={handleChange}
                                    required
                                    multiline
                                    rows={2}
                                    disabled={loading}
                                />
                            </Grid>
                        </Grid>

                        <Divider sx={{ my: 3 }} />

                        <Typography variant="h6" gutterBottom>Receiver Information</Typography>
                        <Grid container spacing={2}>
                            <Grid item xs={12}>
                                <TextField
                                    fullWidth
                                    label="Receiver Name"
                                    name="receiverName"
                                    value={form.receiverName}
                                    onChange={handleChange}
                                    required
                                    disabled={loading}
                                />
                            </Grid>
                            <Grid item xs={12}>
                                <TextField
                                    fullWidth
                                    label="Receiver Address"
                                    name="receiverAddress"
                                    value={form.receiverAddress}
                                    onChange={handleChange}
                                    required
                                    multiline
                                    rows={2}
                                    disabled={loading}
                                />
                            </Grid>
                        </Grid>

                        <Box sx={{ mt: 3, display: 'flex', justifyContent: 'center' }}>
                            <Button
                                variant="contained"
                                onClick={handleSubmit}
                                disabled={loading || !form.senderName || !form.senderAddress || !form.receiverName || !form.receiverAddress}
                            >
                                {loading ? <CircularProgress size={24} /> : 'Generate Label'}
                            </Button>
                        </Box>
                    </Box>
                ) : (
                    <Box sx={{ mt: 2 }}>
                        {labelData && (
                            <>
                                <Paper elevation={2} sx={{ p: 3, mb: 3 }}>
                                    <Typography variant="h6" gutterBottom>Delivery Label Preview</Typography>
                                    <Typography variant="subtitle1" gutterBottom>
                                        Delivery ID: {labelData.deliveryId}
                                    </Typography>
                                    <Box sx={{ my: 2, display: 'flex', justifyContent: 'center' }} className="barcode-container">
                                        <Barcode 
                                            value={labelData.deliveryId}
                                            width={2}
                                            height={100}
                                            fontSize={20}
                                            margin={0}
                                        />
                                    </Box>
                                    <Grid container spacing={2}>
                                        <Grid item xs={6}>
                                            <Typography variant="subtitle2">From:</Typography>
                                            <Typography>{labelData.senderName}</Typography>
                                            <Typography>{labelData.senderAddress}</Typography>
                                        </Grid>
                                        <Grid item xs={6}>
                                            <Typography variant="subtitle2">To:</Typography>
                                            <Typography>{labelData.receiverName}</Typography>
                                            <Typography>{labelData.receiverAddress}</Typography>
                                        </Grid>
                                    </Grid>
                                </Paper>
                                <Box sx={{ display: 'flex', justifyContent: 'center', gap: 2 }}>
                                    <Button 
                                        variant="contained" 
                                        onClick={handleDownload}
                                        disabled={loading}
                                    >
                                        {loading ? <CircularProgress size={24} /> : 'Download PDF'}
                                    </Button>
                                    <Button 
                                        variant="outlined" 
                                        onClick={() => setActiveTab(0)}
                                        disabled={loading}
                                    >
                                        Back to Form
                                    </Button>
                                </Box>
                            </>
                        )}
                    </Box>
                )}
            </Paper>
            <Snackbar
                open={snackbar.open}
                autoHideDuration={6000}
                onClose={handleCloseSnackbar}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
            >
                <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
                    {snackbar.message}
                </Alert>
            </Snackbar>
            <Backdrop
                sx={{ color: '#fff', zIndex: (theme) => theme.zIndex.drawer + 1 }}
                open={loading}
            >
                <CircularProgress color="inherit" />
            </Backdrop>
        </Container>
    );
};

export default Dashboard;
